"use client";

import React from 'react';
import { useRouter } from 'next/navigation';
import { toastInfo } from '@/hooks/use-toast';

export default function ProtectedRedirect({ condition, fallbackPath = '/dashboard' }: { condition: boolean; fallbackPath?: string }) {
  const router = useRouter();
  React.useEffect(() => {
    if (!condition) {
      try { toastInfo('Acceso denegado', 'No tienes permisos para acceder a esa página. Redirigiendo al panel.'); } catch {}
      router.push(fallbackPath);
    }
  }, [condition, fallbackPath, router]);
  return null;
}
